&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Dons-Et-Comp&#233;tences).html#10&quot; title=&quot;FAQ du Manuel des joueurs, section dons et comp&#233;tences&quot;&gt;→&lt;/a&gt; Contr&#244;le des morts-vivants : Combien de temps les morts-vivants restent-ils sous mon contr&#244;le ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Les morts-vivants restent sous le contr&#244;le du personnage ind&#233;finiment jusqu’&#224; ce qu’il les lib&#232;re (ou, si c’est une cr&#233;ature morte-vivante intelligente, jusqu’&#224; ce qu’elle r&#233;ussisse son jet de sauvegarde quotidien pour r&#233;sister au contr&#244;le).  
La dur&#233;e de &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;ce don&lt;/a&gt;&lt;/u&gt; n’est pas bas&#233;e sur la dur&#233;e de 1 minute/niveau du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;contr&#244;le des morts-vivants&lt;/a&gt;&lt;/i&gt; (la r&#233;f&#233;rence au sort est l&#224; pour expliquer comment le personnage peut communiquer avec les morts-vivants et leur donner des ordres, pas pour d&#233;finir sa dur&#233;e, ses composantes mat&#233;rielles, etc).
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Contr&#244;le des morts-vivants est &#233;galement le nom d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Sort-Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;sort&lt;/a&gt; et d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;contr&#244;le des morts-vivants (propri&#233;t&#233;)&quot;&gt;propri&#233;t&#233; d&#39;armure magique&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Le personnage peut recourir &#224; d’immondes pouvoirs n&#233;cromantiques pour prendre le contr&#244;le de cr&#233;atures mortes-vivantes et en faire ses serviteurs.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Condition.&lt;/b&gt; Capacit&#233; de classe permettant de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canaliser de l’&#233;nergie n&#233;gative&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Avantage.&lt;/b&gt; Par une action simple, le personnage peut &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canaliser&lt;/a&gt; l’&#233;nergie n&#233;gative pour r&#233;duire en esclavage des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt; situ&#233;s dans un rayon de neuf m&#232;tres. Les morts-vivants ont droit &#224; un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ce jet est &#233;gal &#224; 10 + 1/2 niveau de pr&#234;tre du personnage + modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;Les morts-vivants qui ratent leur &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; tombent sous le contr&#244;le du personnage et font de leur mieux pour lui ob&#233;ir, comme s’ils &#233;taient sous l’effet d’un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Contr&#244;le-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le des morts-vivants&quot;&gt;contr&#244;le des morts-vivants&lt;/a&gt;&lt;/i&gt;. Les morts-vivants dou&#233;s d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; ont droit &#224; un nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; par jour. Le personnage peut contr&#244;ler n’importe quel nombre de morts-vivants tant que le total de leurs &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; ne d&#233;passe pas son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt;. Si le personnage choisit de canaliser l’&#233;nergie dans ce but, elle n’a pas d’autre effet (elle ne soigne ni ne blesse les cr&#233;atures proches). Si un mort-vivant est sous le contr&#244;le d’une autre cr&#233;ature, le personnage doit faire un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; oppos&#233; &#224; celui de celle-ci quand les ordres entrent en conflit.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;h2 class=&quot;separator&quot;&gt;Version mythique&lt;a class=&quot;headeranchor&quot; id=&quot;Version_mythique_0&quot; href=&quot;#Version_mythique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;i&gt;Le contr&#244;le du personnage sur les morts-vivants est pratiquement absolu.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Condition.&lt;/b&gt; Contr&#244;le des morts-vivants&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Avantage.&lt;/b&gt; Lorsque le personnage contr&#244;le des morts-vivants, le DD des jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; augmente de la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; et les morts-vivants intelligents ne b&#233;n&#233;ficient d’aucune sauvegarde suppl&#233;mentaire au-del&#224; de la premi&#232;re pour y r&#233;sister. Toutes les tentatives effectu&#233;es par des cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Nonmythique.html&quot; title=&quot;non-mythiques&quot;&gt;non-mythiques&lt;/a&gt; pour reprendre le contr&#244;le impos&#233; par le personnage &#233;chouent automatiquement et le personnage gagne un bonus de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; effectu&#233;s pour emp&#234;cher les cr&#233;atures mythiques de s’emparer du contr&#244;le de ses morts-vivants.
